#' Read MS-Decipher O-Search results
#'
#' @description
#' Read an MS-Decipher O-Search Excel report into a
#' [glyexp::GlycoproteomicSE()] with a binary detection matrix. A value of 1
#' indicates identification in the sample and 0 indicates no identification
#' in the supplied report, not biological absence. Values are not abundances
#' or spectral counts.
#'
#' @details
#' This reader is validated against the original `O_Search_15glycans.xlsx`
#' report from JPST001912, generated by MS-Decipher Beta(v2020.03.18).
#' It reads the `PSM` worksheet with columns `MS File`, `Sequence`, `Proteins`,
#' `Hit Type`, and `Delta Name`. This is the legacy O-Search format, not a
#' claim of support for newer O-Search-Pattern exports.
#'
#' Only `TARGET` identifications are retained; `DECOY` rows are excluded.
#' Apply confidence filtering in the search software before exporting: this
#' reader does not impose an additional score threshold. Repeated PSMs,
#' charge states and peptide modifications do not increase the binary value.
#'
#' `Delta Name` is the total peptide glycan composition, with `Neu5Ac`
#' converted to `NeuAc`. The supported tokens are `Hex`, `HexNAc`, and
#' `Neu5Ac`, each followed by an integer count in parentheses. Neither
#' peptide nor protein glycosylation sites are reported by this format:
#' both are returned as `NA_integer_`. The total composition is not assigned
#' to individual residues or split across possible sites.
#'
#' Protein groups separated by `::` use glyread's parsimony inference;
#' the full group is retained in `protein_group`, separated by `;`.
#' Gene names and glycan structures are not inferred. Sample names come from
#' `MS File`. Samples represented only by decoys remain as zero columns if
#' other target identifications exist. A report without targets is rejected.
#'
#' @inheritParams read_strucgp
#' @param glycan_type Glycan type. Defaults to `"O-GalNAc"` for O-Search.
#' @inheritParams read_pglyco3
#' @returns A [glyexp::GlycoproteomicSE()] with binary detection values.
#' @export
read_ms_decipher <- function(
  fp,
  sample_info = NULL,
  glycan_type = "O-GalNAc",
  sample_name_converter = NULL
) {
  fp <- .read_file_input(fp, ".xlsx")
  .validate_read_args(
    sample_info = sample_info,
    glycan_type = glycan_type,
    sample_name_converter = sample_name_converter
  )
  df <- .read_ms_decipher_df(fp)
  samples <- unique(trimws(df[["MS File"]]))
  tidy <- .tidy_ms_decipher(df)
  if (!is.null(sample_name_converter)) {
    samples <- sample_name_converter(samples)
    tidy$sample <- sample_name_converter(tidy$sample)
  }
  samples <- unique(samples)
  sample_info <- .process_sample_info(sample_info, samples)
  keys <- setdiff(names(tidy), c("sample", "protein_group"))
  groups <- .protein_group_annotations(tidy, keys)
  tidy <- dplyr::select(tidy, -"protein_group")
  var_info <- tidy |>
    dplyr::select(-"sample") |>
    dplyr::distinct() |>
    dplyr::mutate(variable = paste0("GP", dplyr::row_number()), .before = 1)
  expr_mat <- matrix(
    0,
    nrow = nrow(var_info),
    ncol = length(samples),
    dimnames = list(var_info$variable, samples)
  )
  identified <- dplyr::left_join(tidy, var_info, by = keys)
  expr_mat[cbind(
    match(identified$variable, var_info$variable),
    match(identified$sample, samples)
  )] <- 1
  var_info <- dplyr::left_join(var_info, groups, by = keys)
  var_info$glycan_composition <- glyrepr::as_glycan_composition(
    var_info$glycan_composition
  )
  .new_glycoproteomic_se(
    expr_mat,
    sample_info,
    var_info,
    glycan_type = glycan_type,
    quant_method = "label-free"
  )
}

.read_ms_decipher_df <- function(fp) {
  if (.is_http_url(fp)) {
    workbook <- tempfile(fileext = ".xlsx")
    on.exit(unlink(workbook), add = TRUE)
    curl::curl_download(fp, workbook, quiet = TRUE)
    fp <- workbook
  }
  if (!"PSM" %in% readxl::excel_sheets(fp)) {
    cli::cli_abort(
      "MS-Decipher O-Search workbook must contain a PSM worksheet."
    )
  }
  readxl::read_excel(fp, sheet = "PSM", col_types = "text")
}

.tidy_ms_decipher <- function(df) {
  required <- c("MS File", "Sequence", "Proteins", "Hit Type", "Delta Name")
  missing <- setdiff(required, names(df))
  if (length(missing)) {
    cli::cli_abort(
      "MS-Decipher PSM worksheet is missing columns: {.val {missing}}."
    )
  }
  df[required] <- lapply(df[required], trimws)
  if (anyNA(df[["MS File"]]) || any(!nzchar(df[["MS File"]]))) {
    cli::cli_abort("MS-Decipher MS File names must not be missing or empty.")
  }
  if (
    anyNA(df[["Hit Type"]]) || any(!df[["Hit Type"]] %in% c("TARGET", "DECOY"))
  ) {
    cli::cli_abort("MS-Decipher Hit Type must be TARGET or DECOY.")
  }
  df <- df[df[["Hit Type"]] == "TARGET", ]
  if (!nrow(df)) {
    cli::cli_abort("MS-Decipher report contains no target identifications.")
  }
  if (
    anyNA(df[required]) ||
      any(vapply(df[required], \(x) any(!nzchar(x)), logical(1)))
  ) {
    cli::cli_abort(
      "Required MS-Decipher target fields must not be missing or empty."
    )
  }
  comp <- df[["Delta Name"]]
  if (
    any(
      !grepl(
        "^(Hex\\([0-9]+\\))?(HexNAc\\([0-9]+\\))?(Neu5Ac\\([0-9]+\\))?$",
        comp
      )
    )
  ) {
    cli::cli_abort(
      "Unsupported MS-Decipher Delta Name composition; no glycan or site is guessed."
    )
  }
  proteins <- strsplit(df$Proteins, "::", fixed = TRUE)
  if (any(!grepl("^[A-Za-z0-9_-]+(::[A-Za-z0-9_-]+)*$", df$Proteins))) {
    cli::cli_abort("Unsupported MS-Decipher protein group notation.")
  }
  # Infer on unique peptide-to-group mappings, not the number of PSMs.
  mapping <- tibble::tibble(
    peptide = df$Sequence,
    protein_group = vapply(proteins, paste, character(1), collapse = ";")
  ) |>
    dplyr::distinct()
  index <- .infer_proteins_internal(mapping$protein_group)
  mapping$protein <- purrr::map2_chr(
    strsplit(mapping$protein_group, ";", fixed = TRUE),
    index,
    \(x, i) x[i]
  )
  tidy <- tibble::tibble(
    peptide = df$Sequence,
    protein_group = vapply(proteins, paste, character(1), collapse = ";"),
    peptide_site = NA_integer_,
    protein_site = NA_integer_,
    glycan_composition = gsub("Neu5Ac", "NeuAc", comp, fixed = TRUE),
    sample = df[["MS File"]]
  )
  dplyr::left_join(tidy, mapping, by = c("peptide", "protein_group"))
}
